export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds) {
    const thresholdResults = [];
    let allPassed = true;

    for (const [metric, min] of Object.entries(thresholds)) {
      const evaluation = evaluations.find((e) => e.id === metric);
      const score = evaluation?.score ?? null;
      const passed = score !== null && score >= min;
      if (!passed) allPassed = false;

      thresholdResults.push({
        metric,
        min,
        score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

