11	  lines.push(`- **Generated At:** ${report.metadata.generatedAt}`);
12	  lines.push(`- **Outputs File:** ${report.metadata.outputsPath}`);
13	  if (report.metadata.referencesPath) {
14	    lines.push(`- **References File:** ${report.metadata.referencesPath}`);
