17	  lines.push('');
18	  lines.push('## Metrics');
19	  lines.push('');
20	  report.metrics.forEach((metric) => {
21	    lines.push(`### ${metric.label}`);
22	    lines.push('');
23	    lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
24	    if (typeof metric.total === 'number') {
25	      lines.push(`- **Total Samples:** ${metric.total}`);
26	    }
27	    if (typeof metric.matches === 'number') {
28	      lines.push(`- **Matches:** ${metric.matches}`);
29	    }
30	    if (typeof metric.flagged === 'number') {
31	      lines.push(`- **Flagged Samples:** ${metric.flagged}`);
32	    }
33	    if (typeof metric.averageDelta === 'number') {
34	      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
35	    }
36	    lines.push('');
37	  });
38	  if (report.thresholds && report.thresholds.length > 0) {
39	    lines.push('## Thresholds');
40	    lines.push('');
41	    report.thresholds.forEach((threshold) => {
42	      const status = threshold.passed ? 'PASS' : 'FAIL';
43	      lines.push(`- **${threshold.metric}:** ${status} (min: ${threshold.min}, score: ${threshold.score ?? 'n/a'})`);
44	    });
45	    lines.push('');
46	  }
47	  lines.push('---');
48	  lines.push('*Generated by FRAI Evaluation Harness*');
